export const LAGOONS_VILLAS = LAGOONS_DATASET.villas;

export function getLagoonsVilla(unit_name: string): LagoonsVilla | undefined {
  return LAGOONS_VILLAS.find(v => v.unit_name === unit_name);
}

export function getLagoonsVillasByCluster(cluster: string): LagoonsVilla[] {
  return LAGOONS_VILLAS.filter(v => v.cluster === cluster);
}
